"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[640],{5537:(e,a,n)=>{n.d(a,{$p:()=>i,W:()=>s,Xv:()=>r,xr:()=>t});let t="(913) 954-3911",r="tel:+19139543911",i=[{slug:"landscape-design",name:"Landscape design & planting",short:"Landscape design",tag:"A vision, brought to life.",image:"hero",description:"A landscape that feels like it has always belonged. We bring the big picture and the smallest details together, from the first planting plan to the final layer of mulch.",items:["Front yard, backyard & whole-property planning","Planting design & landscape installation","Native & climate-adapted gardens","Privacy planting & foundation beds","Sod, soil preparation & landscape renewal","Design concepts & material selections"],body:"A beautiful landscape starts with understanding how you want to live. We consider your home’s architecture, the way sunlight moves across the property, existing trees, drainage and the time you want to spend on upkeep. Then we create a cohesive direction for planting, circulation and gathering spaces.",local:"For Kansas City properties, a plan needs to work through hot summers, cold winters and changing soil conditions. Plant selection, bed preparation and a thoughtful watering plan help a new landscape settle in and develop over time.",faqs:[["Can you work with an existing landscape?","Yes. A project can preserve established trees and favorite plants while reworking tired beds, improving circulation or refreshing the overall planting palette."],["Do I need to know exactly what I want?","A few photos, priorities or even a list of what is not working are a helpful start. The consultation is where we explore a direction together."]]},{slug:"outdoor-living",name:"Patios & outdoor living",short:"Outdoor living",tag:"Make room for more living.",image:"outdoor-living",description:"Turn the space beyond your back door into your favorite place to be. Thoughtful hardscapes give everyday moments a beautiful setting.",items:["Paver & natural-stone patios","Walkways, garden paths & entryways","Retaining walls & landscape masonry","Pergolas & shaded gathering spaces","Fire features & outdoor kitchen planning","Landscape lighting & evening ambiance"],body:"The best outdoor rooms feel connected to the home and comfortable to use. We plan the proportions, routes, materials and planting around the way you gather, cook, unwind and entertain. A quiet seating corner or an expansive terrace deserves the same attention to detail.",local:"Kansas City’s freeze-thaw cycles and rain make base preparation, drainage and material selection especially important. We discuss the practical requirements alongside the aesthetic choices so the finished space is considered from the ground up.",faqs:[["Can you combine a patio with new landscaping?","Yes. Planning hardscape and planting together makes it easier to coordinate drainage, access, lighting and the finished look."],["Can a project be built in phases?","A phased plan can establish the overall direction first and prioritize the areas that matter most. We can discuss sequencing around your goals and budget."]]},{slug:"landscape-care",name:"Lawn & landscape care",short:"Landscape care",tag:"Beautiful, season after season.",image:"garden-design",description:"A well-loved landscape gets better with time. Give your lawn, planting beds and seasonal details the attention they need to keep your property looking considered.",items:["Recurring lawn mowing & edging","Garden-bed weeding & maintenance","Shrub shaping & hedge trimming","Mulch refreshes & bed definition","Spring & fall property cleanups","Seasonal planting & landscape refreshes"],body:"Maintenance should support the design, not simply keep it tidy. We look at the lawn, beds, shrubs and seasonal tasks as one connected landscape, with a scope of care shaped around your property’s needs.",local:"A Midwestern landscape changes throughout the year. Spring cleanup, summer upkeep, fall leaves and timely pruning all call for different attention. We help you plan a practical care schedule for your Kansas City home.",faqs:[["Do you offer one-time cleanups?","You can request a seasonal cleanup or a focused landscape refresh, as well as discuss recurring care. Availability and scope are confirmed during your inquiry."],["Can you care for a landscape you did not install?","Yes. Tell us about your existing property, the areas you need help with and your preferred schedule."]]},{slug:"irrigation-drainage",name:"Irrigation & drainage",short:"Irrigation & drainage",tag:"Good landscapes begin below the surface.",image:"garden-design",description:"Help water move where it belongs. Practical irrigation and drainage planning supports the health of your planting and the way your property works.",items:["Irrigation system planning & installation","Sprinkler troubleshooting & repairs","Controller & watering schedule updates","Drip irrigation for planting beds","Surface drainage & runoff management","Downspout drainage & site grading coordination"],body:"Too little water stresses a garden; too much can undermine it. We review how water arrives, where it collects and how it moves across the site. The goal is a practical solution that works with the property and the landscape around it.",local:"Compacted or clay-heavy soil can make drainage a key consideration in Kansas City. Every property is different, so recommendations begin with site conditions and a conversation about the problems you are seeing.",faqs:[["Can you help with a soggy area in my yard?","Describe where water collects and when it happens. A site assessment helps determine whether grading, runoff routing or a drainage installation is appropriate."],["Can irrigation be updated without replacing everything?","In some cases, repairs, controller adjustments or a targeted zone update can improve an existing system. The right scope depends on its condition."]]},{slug:"tree-shrub-care",name:"Tree & shrub care",short:"Tree & shrub care",tag:"Care for what makes your property yours.",image:"hero",description:"Established trees and healthy shrubs bring structure, shade and character. Keep them part of the bigger picture with thoughtful pruning and landscape care.",items:["Tree & ornamental shrub pruning","Hedge trimming & shaping","Overgrown landscape renewal","Tree planting & replacement","Removal planning & site restoration","Specialist tree evaluation coordination"],body:"Trees and shrubs often define the feeling of a property. We consider their form, location and relationship to your home, paths and surrounding planting when planning care or changes to the landscape.",local:"Timing and species matter when it comes to pruning. We discuss the scope of work and whether specialist evaluation is needed before undertaking more complex tree work.",faqs:[["Can you help decide what to keep or replace?","We can review how existing planting contributes to the landscape and discuss options. Suspected disease, structural concerns or complex tree risks may require a specialist assessment."],["Do you handle large or hazardous removals?","Tell us about the tree and its location. Specialized or hazardous work requires an appropriate evaluation and a confirmed scope before it can be scheduled."]]},{slug:"commercial-landscaping",name:"Commercial landscaping",short:"Commercial landscapes",tag:"A better first impression, every day.",image:"garden-design",description:"Considered landscapes for the places people work, visit and gather. Bring installation and ongoing care into a coordinated plan for your property.",items:["Commercial landscape design & installation","Recurring grounds maintenance","Entryway & common-area planting","Seasonal cleanups & mulch programs","Irrigation & landscape coordination","Property landscape refreshes"],body:"The landscape is often the first experience a visitor has with a property. We help businesses and property managers create welcoming grounds and define a practical maintenance scope, from high-visibility entrances to the everyday details.",local:"For Kansas City commercial properties, seasonal planning helps keep priorities clear throughout the year. We discuss access, property use, maintenance needs and project scheduling before recommending a scope.",faqs:[["What types of properties can inquire?","Offices, retail properties, community spaces and managed residential properties can share their needs for an initial conversation. Service fit and availability are confirmed individually."],["Can you prepare an ongoing maintenance scope?","Yes. Tell us about the property size, existing landscape, priority areas and desired frequency so we can discuss a tailored scope."]]},{slug:"specialty-landscapes",name:"Water features & specialty spaces",short:"Specialty landscapes",tag:"The details that make it personal.",image:"outdoor-living",description:"A quiet water feature, a low-upkeep lawn alternative or a garden with a purpose. Explore the possibilities that make an outdoor space distinctly yours.",items:["Garden fountains & water-feature planning","Decorative ponds & pond landscaping","Artificial turf & lawn alternatives","Pet-friendly outdoor space planning","Small-space & courtyard gardens","Feature planting & garden accents"],body:"Some of the most memorable parts of a landscape are the most personal. We explore what you want a space to feel like, then consider its scale, upkeep and relationship to the rest of the garden before developing the details.",local:"Specialty features need to suit the local climate and the property. Winterization, drainage, access and ongoing care are part of the conversation from the beginning.",faqs:[["Can you add a water feature to an existing garden?","Often, a feature can be integrated into an existing space. Access to utilities, drainage, winter care and maintenance needs will shape the options."],["Is artificial turf suitable for every yard?","It depends on the space and how it will be used. We consider heat exposure, drainage, pets and maintenance expectations before recommending a direction."]]}],s=[{id:"garden-retreat",name:"The garden retreat",category:"Garden & planting",image:"hero",description:"Layered borders, limestone paths and a generous green lawn bring a quiet sense of order to a modern home.",details:"A restrained palette of ornamental grasses, flowering shrubs and mature shade trees creates texture through the seasons. Broad stepping stones connect the house to the garden without interrupting its calm."},{id:"evening-terrace",name:"An evening, well spent",category:"Outdoor living",image:"outdoor-living",description:"A welcoming terrace designed for slow dinners, good company and the last light of the day.",details:"Natural stone, comfortable seating and carefully placed lighting make an outdoor room feel like an extension of the home. Planting softens the edges and frames a private place to gather."},{id:"seasonal-garden",name:"Beauty in every season",category:"Garden & planting",image:"garden-design",description:"Sculptural grasses and generous flowering beds create a garden with a little more to discover.",details:"Repeating plants, varied heights and a clearly defined lawn bring coherence to a lush garden. A balanced mix of texture and seasonal interest keeps the planting considered throughout the year."},{id:"quiet-courtyard",name:"A quieter kind of luxury",category:"Evening gardens",image:"evening-terrace",description:"An intimate terrace where warm light, soft planting and a simple place to sit are all you need.",details:"Warm path lighting, a quiet fire feature and generous planting let the garden take on a different character after sunset. A simple seating arrangement makes room for conversation and a slower pace."}]},6580:(e,a,n)=>{n.d(a,{i3:()=>s,mz:()=>i});var t=n(3427);function r({className:e=""}){return(0,t.jsxs)("svg",{className:e,width:"48",height:"48",viewBox:"0 0 48 48",fill:"none","aria-hidden":"true",children:[(0,t.jsx)("path",{d:"M6 39 24 7l18 32M15 31h18",stroke:"currentColor",strokeWidth:"1.5"}),(0,t.jsx)("path",{d:"M24 25c0-9 8-13 12-13 0 7-4 13-12 13Z",fill:"currentColor"}),(0,t.jsx)("path",{d:"M5 43c12-5 26-5 38 0M12 47c8-3 16-3 24 0",stroke:"currentColor",strokeWidth:"1.2"})]})}function i(){return(0,t.jsxs)("a",{className:"brand",href:"/axel-landscaping/","aria-label":"Axel Landscaping home",children:[(0,t.jsx)(r,{}),(0,t.jsxs)("span",{className:"brand-word",children:["AXEL",(0,t.jsx)("span",{className:"brand-sub",children:"LANDSCAPING"})]})]})}function s({diagonal:e=!1}){return(0,t.jsx)("svg",{width:"20",height:"20",viewBox:"0 0 24 24",fill:"none","aria-hidden":"true",children:e?(0,t.jsx)("path",{d:"M5 19 19 5M5 5h14v14",stroke:"currentColor",strokeWidth:"1.3"}):(0,t.jsx)("path",{d:"M4 12h15m-6-6 6 6-6 6",stroke:"currentColor",strokeWidth:"1.3"})})}}}]);